```php
<?php
/**
 * Custom Site Functions Plugin
 *
 * This plugin adds custom functionalities to an existing website.
 *
 * @package CustomSiteFunctions
 * @version 1.0.0
 * @author Your Name
 */

defined( 'ABSPATH' ) || exit;

/**
 * Main Custom Site Functions Plugin class.
 *
 * @since 1.0.0
 */
final class CustomSiteFunctions {
    /**
     * Plugin version.
     *
     * @since 1.0.0
     * @var string
     */
    public $version = '1.0.0';

    /**
     * Constructor adds necessary actions and filters.
     *
     * @since 1.0.0
     */
    private function __construct() {
        // Custom post type.
        add_action( 'init', array( $this, 'register_custom_post_type' ) );

        // Custom widget.
        add_action( 'widgets_init', array( $this, 'register_custom_widget' ) );

        // Custom shortcodes.
        add_shortcode( 'custom_shortcode_1', array( $this, 'custom_shortcode_1' ) );
        add_shortcode( 'custom_shortcode_2', array( $this, 'custom_shortcode_2' ) );

        // Activation and deactivation hooks.
        register_activation_hook( __FILE__, array( $this, 'activate' ) );
        register_deactivation_hook( __FILE__, array( $this, 'deactivate' ) );
    }

    /**
     * Activate plugin.
     *
     * @since 1.0.0
     */
    public function activate() {
        flush_rewrite_rules();
    }

    /**
     * Deactivate plugin.
     *
     * @since 1.0.0
     */
    public function deactivate() {
        flush_rewrite_rules();
    }

    /**
     * Register custom post type.
     *
     * @since 1.0.0
     */
    public function register_custom_post_type() {
        $args = array(
            'label'         => esc_html__( 'Custom Post Type', 'custom-site-functions' ),
            'description'  => esc_html__( 'This is a custom post type', 'custom-site-functions' ),
            'public'       => true,
            'menu_icon'    => 'dashicons-welcome-write-blog',
            'supports'     => array( 'title', 'editor', 'thumbnail' ),
            'menu_position' => 5,
        );
        register_post_type( 'custom_post_type', $args );
    }

    /**
     * Register custom widget.
     *
     * @since 1.0.0
     */
    public function register_custom_widget() {
        class Custom_Widget extends WP_Widget {
            function Custom_Widget() {
                parent::WP_Widget( false, $name = __( 'Custom Widget', 'custom-site-functions' ) );
            }

            function widget( $args, $instance ) {
                echo '<p>' . $instance['title'] . '</p>';
            }

            function update( $new_instance, $old_instance ) {
                $instance = array();
                $instance['title'] = strip_tags( $new_instance['title'] );
                return $instance;
            }

            function form( $instance ) {
                if ( isset( $instance['title'] ) ) {
                    $title = $instance['title'];
                } else {
                    $title = __( 'New Title', 'custom-site-functions' );
                }
                ?>
                <p>
                    <label for="<?php echo $this->get_field_id( 'title' ); ?>"><?php _e( 'Title:' ); ?></label>
                    <input class="widefat" id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" type="text" value="<?php echo esc_attr( $title ); ?>">
                </p>
                <?php
            }
        }

        register_widget( 'Custom_Widget' );
    }

    /**
     * Custom shortcode 1.
     *
     * @since 1.0.0
     * @param array $atts Attributes.
     * @return string Shortcode output.
     */
    public function custom_shortcode_1( $atts ) {
        $a = esc_attr( shortcode_atts(
            array(
                'text' => __( 'Default text', 'custom-site-functions' ),
            ),
            $atts,
            'custom_shortcode_1'
        ) );

        return '<p>' . $a['text'] . '</p>';
    }

    /**
     * Custom shortcode 2.
     *
     * @since 1.0.0
     * @param array $atts Attributes.
     * @return string Shortcode output.
     */
    public function custom_shortcode_2( $atts ) {
        $a = esc_attr( shortcode_atts(
            array(
                'text' => __( 'Default text', 'custom-site-functions' ),
            ),
            $atts,
            'custom_shortcode_2'
        ) );

        return '<p>' . $a['text'] . '</p>';
    }
}

(new CustomSiteFunctions);
