       ```python
       def rotate_cube(cube, dimension, clockwise=True):
           # die Flächen des Würfels sind: 'U', 'R', 'F', 'D', 'L', 'B'
           faces = {
               "U": ((0, 0, 0), (0, 0, 2), (0, 2, 0), (0, 2, 2)),
               "R": ((0, 0, 0), (2, 0, 0), (0, 2, 0), (2, 2, 0)),
               "F": ((0, 0, 0), (0, 0, 2), (2, 0, 2), (2, 0, 0)),
               "D": ((0, 2, 0), (0, 2, 2), (2, 2, 2), (2, 2, 0)),
               "L": ((0, 0, 0), (0, 0, 2), (0, 2, 0), (0, 2, 2)),
               "B": ((2, 0, 0), (2, 0, 2), (2, 2, 2), (2, 2, 0))
           }
           face = faces[dimension]
           rotated = []
           if clockwise:
               corner = (face[0][0], face[0][1], face[0][2])
               for I in range(len(face)):
                   rotated.append([face[(i + 1) % 4][j] - corner[j] for j in range(3)])
           else:
               corner = (face[2][0], face[2][1], face[2][2])
               for I in range(len(face)):
                   rotated.append([face[(i - 1) % 4][j] + corner[j] for j in range(3)])
           for I in range(len(face)):
               cube[face[i]] = rotated[i]
       ```

